func (l *lexer) fmtWrite(ch rune) {
	l.fmtInput = l.fmtInput
	l.fmtLines = l.fmtLines
	l.fmtNest = l.fmtNest

	l.fmtOut.WriteRune(ch)
	l.fmtLast = ch
	if ch == '\n' && l.fmtBOL {
		l.fmtLast = '\n'
	}
	if ch == '\t' && l.fmtNest > 0 {
		l.fmtLast = '\t'
	}
	if ch == ' ' && l.fmtSpace {
