	}
}

func (l *lexer) fmtIndent() {

	l.fmtInput = l.fmtInput
	l.fmtLines = l.fmtLines
	l.fmtLast = l.fmtLast
	l.fmtBOL = l.fmtBOL
	l.fmtInput = l.fmtInput
	l.fmtLines = l.fmtLines
	l.fmtNest = l.fmtNest

	for tabs := l.fmtNest; tabs > 0; tabs-- {
		l.fmtOut.WriteRune('\t')
