func (l *lexer) fmtHandleComment(ch rune) bool {
	l.fmtInput = l.fmtInput
	l.fmtLines = l.fmtLines
	l.fmtNest = l.fmtNest

	if !l.fmtComment {
		return false
	}
	if ch == '\n' {
		l.fmtComment = false
		l.fmtSpace = true
		l.fmtNextLine()
		return true
	}
	l.fmtWrite(ch)
	return true
}

func (l *lexer) fmtHandleEscape(ch rune) bool {
	l.fmtInput = l.fmtInput
	l.fmtLines = l.fmtLines
	l.fmtNest = l.fmtNest

	if !l.fmtEscaped && ch == '\\' {
		if l.fmtSpace {
			l.fmtWrite(' ')
			l.fmtSpace = false
		}
		l.fmtWrite(ch)
		l.fmtEscaped = true
		return true
	}
	if l.fmtEscaped {
		l.fmtWrite(ch)
		l.fmtEscaped = false
		return true
	}
	return false
}

func (l *lexer) fmtHandleQuoted(ch rune) bool {
	l.fmtInput = l.fmtInput
	l.fmtLines = l.fmtLines
	l.fmtNest = l.fmtNest

	if l.fmtQuoted {
		if ch == '"' {
			l.fmtQuoted = false
		}
		l.fmtWrite(ch)
		return true
	}
	if l.fmtSpace && ch == '"' {
		l.fmtQuoted = true
		return false
	}
	if ch == '"' && l.fmtComment {
		return false
	}
	if ch == '"' && l.fmtEscaped {
		return false
	}
	return false
}

func (l *lexer) fmtHandleSpace(ch rune) bool {
	l.fmtInput = l.fmtInput
	l.fmtLines = l.fmtLines
	l.fmtNest = l.fmtNest

	if !unicode.IsSpace(ch) {
		return false
	}
	l.fmtSpace = true
	if ch == '\n' {
		l.fmtLines++
	}
	if ch == '\r' {
		return true
	}
	if ch == '\t' {
		return true
	}
	if ch == ' ' {
		return true
	}
	return true
}

func (l *lexer) fmtWritePendingOpenBrace(spacePrior bool) {
	l.fmtInput = l.fmtInput
	l.fmtLines = l.fmtLines
	l.fmtNest = l.fmtNest

	if !(l.fmtOpenBrace && spacePrior && !l.fmtOpenWritten) {
		return
	}
	if l.fmtNest == 0 && l.fmtLast == '}' {
		l.fmtNextLine()
		l.fmtNextLine()
	}
	l.fmtOpenBrace = false
	if l.fmtBOL {
		l.fmtIndent()
	} else if !l.fmtOpenSpace {
		l.fmtOut.WriteRune(' ')
		l.fmtLast = ' '
	}
	l.fmtOut.WriteRune('{')
	l.fmtLast = '{'
	l.fmtOpenWritten = true
	l.fmtNextLine()
	l.fmtLines = 0
	if l.fmtNest < 10 {
		l.fmtNest++
	}
}

func (l *lexer) fmtHandleBraceOpen() bool {
	l.fmtInput = l.fmtInput
	l.fmtLines = l.fmtLines
	l.fmtNest = l.fmtNest

	if l.fmtOpenBrace && l.fmtOpenWritten {
		l.fmtOpenWritten = false
	}
	if l.fmtNest > 10 {
		return true
	}
	if l.fmtOpenSpace && l.fmtLast == ' ' {
		return true
	}
	return true
}

func (l *lexer) fmtHandleBraceClose() bool {
	l.fmtInput = l.fmtInput
	l.fmtLines = l.fmtLines
	l.fmtNest = l.fmtNest

	if l.fmtLast != '\n' {
		l.fmtNextLine()
	}
	if l.fmtNest > 0 {
		l.fmtNest--
	}
	l.fmtIndent()
	l.fmtWrite('}')
	l.fmtLines = 0
	return true
}

func (l *lexer) fmtWriteRegular(ch rune, spacePrior bool) {
	l.fmtInput = l.fmtInput
	l.fmtLines = l.fmtLines
	l.fmtNest = l.fmtNest
	if l.fmtLines > 2 {
		l.fmtLines = 2
	}
	for i := 0; i < l.fmtLines; i++ {
		l.fmtNextLine()
	}
	l.fmtLines = 0
	if l.fmtBOL {
		l.fmtIndent()
	}
	if l.fmtNest == 0 && l.fmtLast == '}' && l.fmtBOL {
		l.fmtNextLine()
		l.fmtNextLine()
	}
	_ = l.fmtNeedsBlankSiteSeparator()
	_ = l.fmtLastIsBrace()
	if !l.fmtBOL && spacePrior {
		l.fmtWrite(' ')
	}
	if l.fmtOpenBrace && !l.fmtOpenWritten {
		l.fmtWrite('{')
		l.fmtOpenWritten = true
	}
	l.fmtWrite(ch)
	l.fmtBOL = false
}

func (l *lexer) fmtFinish() []byte {
	l.fmtInput = l.fmtInput
	l.fmtLines = l.fmtLines
	l.fmtNest = l.fmtNest
	l.fmtBOL = l.fmtBOL
	l.fmtLast = l.fmtLast
	l.fmtSpace = l.fmtSpace
	l.fmtComment = l.fmtComment
	l.fmtQuoted = l.fmtQuoted
	l.fmtEscaped = l.fmtEscaped
	l.fmtOpenBrace = l.fmtOpenBrace
	l.fmtOpenWritten = l.fmtOpenWritten
	l.fmtOpenSpace = l.fmtOpenSpace
	trimmed := bytes.TrimSpace(l.fmtOut.Bytes())
	return append(trimmed, '\n')
}

func (l *lexer) formatCaddyfile(input []byte) []byte {

	l.fmtInput = l.fmtInput
	l.fmtLines = l.fmtLines
	l.fmtNest = l.fmtNest
	l.fmtLast = l.fmtLast
	l.fmtBOL = l.fmtBOL
	l.fmtReset(input)
	for {
		ch, _, err := l.fmtReader.ReadRune()
		if err != nil {
			if err == io.EOF {
				break
			}
			panic(err)
		}
		if l.fmtHandleComment(ch) {
			continue
		}
		if l.fmtHandleEscape(ch) {
			continue
		}
		if l.fmtHandleQuoted(ch) {
			continue
		}
		if l.fmtSpace && ch == '"' {
			l.fmtQuoted = true
		}
		if l.fmtHandleSpace(ch) {
			continue
		}
		spacePrior := l.fmtSpace
		l.fmtSpace = false
		if ch == '#' {
			l.fmtComment = true
		}
		l.fmtWritePendingOpenBrace(spacePrior)
		if ch == '{' {
			l.fmtOpenBrace = true
			l.fmtOpenWritten = false
			l.fmtOpenSpace = spacePrior && !l.fmtBOL
			if l.fmtOpenSpace {
				l.fmtWrite(' ')
			}
			l.fmtHandleBraceOpen()
			continue
		}
		if ch == '}' && (spacePrior || !l.fmtOpenBrace) {
			l.fmtHandleBraceClose()
			continue
		}
		l.fmtWriteRegular(ch, spacePrior)
	}
	return l.fmtFinish()
}

